CREATE TYPE "ScanStatus" AS ENUM ('QUEUED','RUNNING','COMPLETED','FAILED');
CREATE TYPE "FindingKind" AS ENUM ('SAST','SCA','SECRET','IAC');
CREATE TYPE "Severity" AS ENUM ('CRITICAL','HIGH','MEDIUM','LOW','INFO');
CREATE TYPE "FindingStatus" AS ENUM ('OPEN','FIXED','IGNORED','NEEDS_HUMAN');
CREATE TYPE "FixStatus" AS ENUM ('PENDING','VERIFIED','FAILED','ISSUE_OPENED','PR_OPENED');
CREATE TABLE "Installation" ("id" TEXT PRIMARY KEY,"githubInstallationId" BIGINT NOT NULL UNIQUE,"accountLogin" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Repo" ("id" TEXT PRIMARY KEY,"githubId" BIGINT NOT NULL UNIQUE,"fullName" TEXT NOT NULL UNIQUE,"defaultBranch" TEXT NOT NULL,"installationId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Repo_installationId_fkey" FOREIGN KEY ("installationId") REFERENCES "Installation"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Scan" ("id" TEXT PRIMARY KEY,"repoId" TEXT NOT NULL,"pullNumber" INTEGER,"baseSha" TEXT,"headSha" TEXT,"status" "ScanStatus" NOT NULL DEFAULT 'QUEUED',"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "Scan_repoId_fkey" FOREIGN KEY ("repoId") REFERENCES "Repo"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Finding" ("id" TEXT PRIMARY KEY,"scanId" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"kind" "FindingKind" NOT NULL,"ruleId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"severity" "Severity" NOT NULL,"cvss" DOUBLE PRECISION NOT NULL,"path" TEXT NOT NULL,"line" INTEGER NOT NULL,"endLine" INTEGER,"evidence" TEXT,"reachable" BOOLEAN NOT NULL DEFAULT false,"reasoning" JSONB NOT NULL,"status" "FindingStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Finding_scanId_fkey" FOREIGN KEY ("scanId") REFERENCES "Scan"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Finding_scanId_fingerprint_key" UNIQUE ("scanId","fingerprint"));
CREATE TABLE "FixAttempt" ("id" TEXT PRIMARY KEY,"findingId" TEXT NOT NULL,"status" "FixStatus" NOT NULL DEFAULT 'PENDING',"diff" TEXT,"verification" JSONB,"prUrl" TEXT,"issueUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FixAttempt_findingId_fkey" FOREIGN KEY ("findingId") REFERENCES "Finding"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"githubId" BIGINT NOT NULL UNIQUE,"login" TEXT NOT NULL,"email" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLogEntry" ("id" TEXT PRIMARY KEY,"scanId" TEXT,"action" TEXT NOT NULL,"actor" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLogEntry_scanId_fkey" FOREIGN KEY ("scanId") REFERENCES "Scan"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "ProcessedWebhookDelivery" ("id" TEXT PRIMARY KEY,"deliveryId" TEXT NOT NULL UNIQUE,"event" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OsvCacheEntry" ("id" TEXT PRIMARY KEY,"packageName" TEXT NOT NULL,"ecosystem" TEXT NOT NULL,"version" TEXT NOT NULL,"vulnerabilities" JSONB NOT NULL,"fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OsvCacheEntry_packageName_ecosystem_version_key" UNIQUE ("packageName","ecosystem","version"));
